new:
// ── Per-screen layout profiles ─────────────────────────────────────────
// `barConfig.layout` is the default profile: every output renders it unless
// it owns an entry under `barConfig.screens`. A screen profile carries the
// same shape as the bar subtree itself -- a `layout`, plus an optional
// `enabled` -- so a second screen is a bar config in miniature rather than a
// second, divergent schema to learn.
//
// An output with no entry is not the same as an output with an empty one.
// The first inherits; the second is deliberately blank. Keeping those
// distinct is what lets "give this monitor its own bar" be an explicit and
// reversible act instead of a side effect of having touched the screen.
property var screenLayouts: ({})

// Each profile's widgets, as layoutWidgets is the default's. Every bar
// surface keeps its own pool and hands it the widgets its screen renders, so
// keys only have to be unique within a profile -- and each profile keeps its
// own memo, which is what lets a widget keep its instance through a drag on
// the screen it was dragged on.
property var screenMemos: ({})
readonly property var screenWidgets: {
  var out = ({})
  var layouts = screenLayouts
  for (var name in layouts) out[name] = BarModel.layoutWidgets(layouts[name], screenMemos[name])
  return out
}

// Transparency is deliberately NOT per screen. The colour a clear bar draws
// with is sampled from the wallpaper, and every widget takes it from the
// shared `bar.barForeground`, so two screens cannot disagree about the
// background and both stay readable.
property var screenDisabled: ({})

// Screens whose bar is switched off are dropped from the model rather than
// parked off-screen the way the global bar-off toggle does it. That toggle
// is a hotkey and has to be cheap to reverse; this is a config decision, and
// destroying the surface is what actually gives the exclusion zone back so
// windows can use the full height of that screen.
readonly property var enabledScreens: {
  var serial = barConfigSerial
  var disabled = screenDisabled
  var all = Quickshell.screens
  var out = []
  for (var i = 0; i < all.length; i++) {
    if (disabled[String(all[i].name || "")] === true) continue
    out.push(all[i])
  }
  return out
}

// Nothing is drawn until the host has handed over the widget registry.
readonly property bool hostReady: barWidgetRegistry !== null

function hasScreenProfile(screenName) {
  var key = String(screenName || "")
  return key !== "" && screenLayouts[key] !== undefined
}

function layoutFor(screenName) {
  var key = String(screenName || "")
  var own = key !== "" ? screenLayouts[key] : undefined
  return own !== undefined ? own : layoutConfig
}

function widgetsFor(screenName) {
  var key = String(screenName || "")
  var own = key !== "" ? screenWidgets[key] : undefined
  return own !== undefined ? own : layoutWidgets
}

function memoFor(screenName) {
  return hasScreenProfile(screenName) ? screenMemos[String(screenName)] : widgetMemo
}

function windowScreenName(window) {
  return window && window.screen ? String(window.screen.name || "") : ""
}

// The keys a section shows on the surface that owns `pool`. A list with no
// pool yet -- the tray's drawer before its slot hands it one -- makes no
// slots anyway, so the default is only ever a placeholder.
function sectionKeys(pool, region) {
  var widgets = pool && pool.widgets ? pool.widgets : layoutWidgets
  var keys = widgets && widgets.sections ? widgets.sections[region] : null
  return Array.isArray(keys) ? keys : []
}

// Where a write for a screen lands: its own profile when it has one, the
// default otherwise. Shaped like a whole config so upstream's moveEntry,
// which only knows `config.bar.layout`, edits the profile in place.
// Dragging a widget on an inheriting output edits the default profile, which
// is what the user sees happening -- that bar is showing the default.
// Creating a profile is the panel's job, and stays a deliberate act.
function profileConfig(config, screenName) {
  var key = String(screenName || "")
  var screens = Util.isPlainObject(config.bar) ? config.bar.screens : null
  if (key === "" || !Util.isPlainObject(screens) || !Util.isPlainObject(screens[key])) return config
  var profile = screens[key]
  if (!Util.isPlainObject(profile.layout)) profile.layout = {}
  return { bar: { layout: profile.layout } }
}

// ── the centre anchor, retired ─────────────────────────────────────────
// Omarchy split the center section at its anchor into centerBegin, center
// and centerEnd, and migrated shell.json to match -- except a config whose
// bar is not the built-in one, which is exactly what a 5bars config is. So
// the same split happens here, for the default and for every screen profile:
// the anchor stays in the box, what flanked it moves to the sections either
// side, and a center list without its anchor stays whole. A profile that
// named no anchor of its own used the default's, and is split by that.
function splitCenterAt(layout, anchor) {
  if (!Util.isPlainObject(layout)) return false
  var id = Util.canonicalWidgetId(String(anchor || ""))
  var center = Array.isArray(layout.center) ? layout.center : []
  var at = -1
  for (var i = 0; id !== "" && i < center.length; i++) {
    if (Util.canonicalWidgetId(entryId(center[i])) === id) { at = i; break }
  }
  if (at === -1) return false
  layout.centerBegin = (Array.isArray(layout.centerBegin) ? layout.centerBegin : []).concat(center.slice(0, at))
  layout.centerEnd = center.slice(at + 1).concat(Array.isArray(layout.centerEnd) ? layout.centerEnd : [])
  layout.center = [center[at]]
  return true
}

function profileAnchor(profile, fallback) {
  var own = Util.isPlainObject(profile) ? profile.centerAnchor : undefined
  return own !== undefined && own !== null ? own : fallback
}

// What is drawn, split on a copy until the file itself is migrated, so the
// bar looks right from its first frame.
function profileLayout(layout, anchor) {
  var copy = Util.isPlainObject(layout) ? JSON.parse(JSON.stringify(layout)) : layout
  splitCenterAt(copy, anchor)
  return normalizeLayout(copy)
}

function hasCenterAnchors(config) {
  if (config.centerAnchor !== undefined) return true
  if (!Util.isPlainObject(config.screens)) return false
  for (var name in config.screens) {
    if (Util.isPlainObject(config.screens[name]) && config.screens[name].centerAnchor !== undefined) return true
  }
  return false
}

// The file has to follow, not just the bar: a drag writes indexes into the
// sections as drawn, and moveEntry refuses an index that does not match.
// Once per instance, and later, since this is reached from the config
// change it is about to cause.
property bool centerAnchorsMigrated: false

function migrateCenterAnchors() {
  if (centerAnchorsMigrated) return
  if (!root.shell || typeof root.shell.mutateShellConfig !== "function") return
  centerAnchorsMigrated = true
  root.shell.mutateShellConfig(function(config) {
    if (!Util.isPlainObject(config.bar)) return
    var bar = config.bar
    var fallback = bar.centerAnchor
    if (Util.isPlainObject(bar.screens)) {
      for (var name in bar.screens) {
        var profile = bar.screens[name]
        if (!Util.isPlainObject(profile)) continue
        root.splitCenterAt(profile.layout, root.profileAnchor(profile, fallback))
        delete profile.centerAnchor
      }
    }
    root.splitCenterAt(bar.layout, fallback)
    delete bar.centerAnchor
  })
}

function normalizeScreenLayouts(screens, fallbackAnchor) {
  var out = ({})
  if (!Util.isPlainObject(screens)) return out
  for (var name in screens) {
    var profile = screens[name]
    if (!Util.isPlainObject(profile)) continue
    out[String(name)] = profileLayout(profile.layout, profileAnchor(profile, fallbackAnchor))
  }
  return out
}

function layoutEntries(region, screenName) {
  var serial = barConfigSerial
  var layout = layoutFor(screenName)
  var entries = layout ? layout[region] : null
  return Array.isArray(entries) ? entries : []
}

  layoutConfig = profileLayout(config.layout, config.centerAnchor)

  // Reassigned only when a profile really changed: every surface rendering
  // one re-reads its widgets off screenWidgets, and a write that only
  // touched the default should leave those surfaces alone.
  var nextScreens = normalizeScreenLayouts(config.screens, config.centerAnchor)
  if (JSON.stringify(screenLayouts) !== JSON.stringify(nextScreens)) {
    for (var screenName in nextScreens) if (!screenMemos[screenName]) screenMemos[screenName] = ({})
    screenLayouts = nextScreens
  }
  // Stored as `enabled: false`, read as "disabled", so that a profile which
  // says nothing about it is on -- the same inherit-by-omission rule the
  // layout follows.
  var nextDisabled = ({})
  if (Util.isPlainObject(config.screens)) {
    for (var name in config.screens) {
      var profile = config.screens[name]
      if (Util.isPlainObject(profile) && profile.enabled === false) nextDisabled[String(name)] = true
    }
  }
  if (JSON.stringify(screenDisabled) !== JSON.stringify(nextDisabled)) screenDisabled = nextDisabled
  barConfigSerial++

  if (!centerAnchorsMigrated && hasCenterAnchors(config)) Qt.callLater(migrateCenterAnchors)
}

onLayoutWidgetsChanged: if (barDragSource && JSON.stringify(dragWidgets().sections) !== barDragKeys) Qt.callLater(clearBarDrag)
