  id: barWindow

  // The output this surface is drawn on, and what it renders there: its own
  // profile, or the default. Everything below reads its widgets off this.
  readonly property string screenName: root.windowScreenName(barWindow)
  readonly property var widgets: root.widgetsFor(screenName)

// What the surface renders (BarPanel.widgets): the keys it makes widgets
// for, and each key's entry.
property var widgets: null
// Key -> its WidgetHost, and the ModuleSlot showing it.
property var hosts: ({})

old:
function injectProps() {
  var target = activeItem
  if (!target) return
  // Ahead of bar: a widget can start laying itself out the moment it has
  // a bar, as the indicators do by reporting which are already active.
  if ("fixedEdge" in target) target.fixedEdge = fixedEdge
  if ("bar" in target) target.bar = firstParty
    ? root : root.pluginBarApiFor(pluginApiId, moduleName, registered)

new:
function injectProps() {
  var bar = root
  var target = activeItem
  if (!bar || !target) return
  // Ahead of bar: a widget can start laying itself out the moment it has
  // a bar, as the indicators do by reporting which are already active.
  if ("fixedEdge" in target) target.fixedEdge = fixedEdge
  // 5bars' own Studio panel needs the real bar: it reads the widget
  // registry, the theme palette and the shell off it, none of which the
  // PluginBarApi facade carries. Every OTHER third-party widget keeps the
  // sandbox upstream gave it.
  if ("bar" in target) target.bar = (firstParty || pluginApiId === "cinco.5bars")
    ? bar : bar.pluginBarApiFor(pluginApiId, moduleName, registered)

property bool transparent: false
// ── Pills ──────────────────────────────────────────────────────────────
// `bar.pills: true` stops painting the strip and gives every widget a
// capsule of the theme bar background instead, so the wallpaper shows
// between widgets. It is a third look, not a flavour of `transparent`: a
// transparent strip has to sample the wallpaper to pick a readable text
// colour, while a capsule carries its own contrast and keeps the theme
// foreground. Pills therefore win over a clear background -- with both set
// the strip is clear because of the pills, and the sampled-colour path is
// never entered. Global, like transparency, and for the same reason: every
// surface reads the one shared foreground.
property bool pills: false
// ── What a capsule is painted with ─────────────────────────────────────
// Colour is theme business, so it is read from shell.toml like every other
// surface in the shell rather than from shell.json, which holds the layout.
// `[bar] pill` and `pill-alpha` set the fill, `pill-border` and
// `pill-border-alpha` the rim, and a named group can have its own pair --
// `pill-sys` for `"pill": "sys"`. Unset, a capsule is the bar background at
// 0.85 and a hairline of the bar text, which is what pills looked like
// before any of this was configurable.
//
// A theme that ships these swaps them with itself. A machine that wants one
// colour whatever the theme is puts them in ~/.config/omarchy/shell.toml,
// where user keys win and survive a theme switch.
//
// A token is any colour the theme ships: a name from its colors.toml
// (`lighter_background`, `selection`, `green`, ...), one of the shell's
// roles (`foreground`, `accent`, `urgent`, `muted`, `background`,
// `transparent`), a hex colour, or the name of another shell.toml key.
// shell.json carries the same four, under `bar.pillColor`, `pillOpacity`,
// `pillBorderColor` and `pillBorderOpacity`. They are the user's half of the
// cascade the shell itself runs on -- a theme's shell.toml sets the look, a
// user's file wins over it -- and they are what the panel can write, which
// shell.toml is not: a bar plugin reaches config through
// `mutateShellConfig`, and that is shell.json only. Empty and -1 mean unset.
property string configPillColor: ""
property string configPillBorderColor: ""
property real configPillOpacity: -1
property real configPillBorderOpacity: -1

function normalizePillAlpha(value) {
  if (value === undefined || value === null) return -1
  var n = Number(value)
  if (!isFinite(n)) return -1
  return Math.min(1, Math.max(0, n))
}

// Specificity first, source second: a group's own token beats the generic
// one, and within each level the user beats the theme. A group's colour is
// therefore theme-level only, which is also all the panel could express.
function pillToken(group, suffix, fallback) {
  var override = suffix === "-border" ? configPillBorderColor : configPillColor
  var generic = override !== "" ? override : Color.pick("bar.pill" + suffix, fallback)
  if (group === "") return generic
  return Color.pick("bar.pill-" + group + suffix, generic)
}

function pillAlpha(group, suffix, fallback) {
  var override = suffix === "-border" ? configPillBorderOpacity : configPillOpacity
  var generic = override >= 0 ? override : Color.pickAlpha("bar.pill" + suffix + "-alpha", fallback)
  if (group === "") return generic
  return Color.pickAlpha("bar.pill-" + group + suffix + "-alpha", generic)
}

// All of this reaches past the bar into Color and Util. The anchors cover
// the text of Bar.qml and say nothing about those, so a release that takes
// one away would otherwise turn every capsule into a binding error. Checked
// once, and what is left is the look pills had before any of it was
// configurable, drawn with bindings the stock bar itself uses.
readonly property bool pillThemingAvailable: typeof Color.pick === "function"
  && typeof Color.pickAlpha === "function"
  && typeof Color.flatColor === "function"
  && typeof Util.alpha === "function"

function pillFillFor(group) {
  if (!pillThemingAvailable)
    return Qt.rgba(background.r, background.g, background.b, 0.85)
  return Util.alpha(pillColor(pillToken(group, "", ""), Color.bar.background),
    pillAlpha(group, "", 0.85))
}

function pillBorderFor(group) {
  if (!pillThemingAvailable)
    return Qt.rgba(barForeground.r, barForeground.g, barForeground.b, 0.10)
  return Util.alpha(pillColor(pillToken(group, "-border", ""), Color.bar.text),
    pillAlpha(group, "-border", 0.10))
}

// ── The theme's own palette ────────────────────────────────────────────
// Color keeps five colours off the theme's colors.toml -- foreground,
// background, accent, urgent, muted -- and a capsule usually wants one of
// the others. `lighter_background` is the shade a card is drawn in, and
// every stock theme defines it, along with `selection`, `dark_background`
// and the sixteen terminal colours. They are read here rather than waited
// for, so a pill can name any colour the theme actually ships without the
// theme having to know that pills exist.
//
// Re-read when the palette changes rather than when the file does. A theme
// switch stages the new theme elsewhere and renames the directory into
// place, which a file watch does not survive, then hands the shell the new
// colours over IPC -- so Color's own properties landing is the signal that
// the file on disk is now the new one.
property var themePalette: ({})

function loadThemePalette(raw) {
  var out = ({})
  var lines = String(raw || "").split("\n")
  for (var i = 0; i < lines.length; i++) {
    var kv = lines[i].match(/^\s*([A-Za-z0-9_-]+)\s*=\s*["\']?(#[0-9A-Fa-f]{6})/)
    if (kv) out[kv[1].toLowerCase()] = kv[2]
  }
  themePalette = out
}

FileView {
  id: themePaletteFile
  path: root.stateHome + "/omarchy/current/theme/colors.toml"
  preload: true
  printErrors: false
  onLoaded: root.loadThemePalette(text())
  onLoadFailed: root.loadThemePalette("")
}

Connections {
  target: Color
  // A palette that stops signalling costs the theme-switch refresh, not the
  // whole bar.
  ignoreUnknownSignals: true
  function onBackgroundChanged() { themePaletteFile.reload() }
  function onAccentChanged() { themePaletteFile.reload() }
}

// A pill token, resolved: a name from the theme's palette first, then the
// shell's own vocabulary -- a role, a hex colour, or another shell.toml key.
function pillColor(token, fallback) {
  var key = String(token || "").replace(/^\s+|\s+$/g, "").toLowerCase()
  var hex = key !== "" ? themePalette[key] : undefined
  return hex !== undefined ? hex : Color.flatColor(token, fallback)
}

// A layout entry's `pill` key: a string joins it to the neighbours carrying
// the same one, `false` asks for no capsule, and anything else -- usually
// nothing at all -- means a capsule of its own.
function pillGroupOf(entry) {
  var settings = entrySettings(entry)
  var value = settings ? settings.pill : undefined
  return typeof value === "string" && value !== "" ? value : ""
}

// The nearest descendant that masks its input region, or null. A widget that
// reserves space it does not paint has to say so somehow, or the empty part
// would swallow hovers and clicks, and a containmentMask is how it says it.
// That makes the mask the one description of the painted region a widget
// offers without being asked for it. The tray is the case in the stock bar:
// collapsed, it still holds the width its drawer slides into, so a capsule
// drawn over the whole slot is four fifths empty. Depth is capped because
// this walks a widget's private tree, which is not ours to know.
function maskedDescendant(item, depth) {
  if (!item) return null
  if (item.containmentMask) return item
  if (depth <= 0 || item.children === undefined) return null
  var kids = item.children
  for (var i = 0; i < kids.length; i++) {
    var found = maskedDescendant(kids[i], depth - 1)
    if (found) return found
  }
  return null
}

// Where that mask starts and ends along the bar axis, as [start, end], or
// null when it admits everything or nothing. Sampled rather than solved: a
// mask is a predicate, not a shape. A 2px sweep with a 1px walk back costs
// under a hundred calls on a 160px slot, which is nothing beside the repaint
// it feeds, and it assumes only that the painted part is in one piece.
function maskSpan(item) {
  var mask = item ? item.containmentMask : null
  if (!mask || typeof mask.contains !== "function") return null
  var extent = vertical ? item.height : item.width
  var cross = (vertical ? item.width : item.height) / 2
  if (!(extent > 0)) return null
  var first = -1
  for (var p = 0; p < extent; p += 2) {
    if (mask.contains(vertical ? Qt.point(cross, p) : Qt.point(p, cross))) { first = p; break }
  }
  if (first === -1) return null
  while (first > 0 && mask.contains(vertical ? Qt.point(cross, first - 1) : Qt.point(first - 1, cross))) first -= 1
  var last = -1
  for (var q = extent - 1; q >= 0; q -= 2) {
    if (mask.contains(vertical ? Qt.point(cross, q) : Qt.point(q, cross))) { last = q; break }
  }
  while (last < extent - 1 && mask.contains(vertical ? Qt.point(cross, last + 1) : Qt.point(last + 1, cross))) last += 1
  if (last <= first) return null
  return [first, last + 1]
}

pills = config.pills === true
configPillColor = typeof config.pillColor === "string" ? config.pillColor : ""
configPillBorderColor = typeof config.pillBorderColor === "string" ? config.pillBorderColor : ""
configPillOpacity = normalizePillAlpha(config.pillOpacity)
configPillBorderOpacity = normalizePillAlpha(config.pillBorderOpacity)
var look = config.background || (config.transparent === true ? "none" : "opaque")
// Never ask for the sampled foreground while pills are on: the capsules
// are the contrast, and the theme text colour is the one that reads on
// them. The background is left in the file untouched, so switching pills
// off lands on whatever look it describes.
setRequestedTransparency(!pills && look === "none")

HoverHandler { id: moduleHover }

// ── The capsule ────────────────────────────────────────────────────────
// One rectangle per group, painted by the group's first member and sized
// to reach its last. A rectangle per slot would leave a seam wherever two
// of them meet -- a Rectangle borders all four of its sides -- so the slot
// that opens a group owns the whole shape and the others draw nothing.
// The shape still lands behind every member: it is declared before this
// slot's own loaders, and a positioner's later children paint over it.
//
// A widget that paints its own backdrop opts out with `"pill": false`.
// A widget in the tray's drawer already sits inside the tray's capsule.
readonly property bool pillEnabled: root.pills && slot.region !== "tray"
  && root.entrySettings(slot.entry).pill !== false
readonly property string pillGroup: root.pillGroupOf(slot.entry)

// Neighbours are read off the positioner rather than off the layout list,
// because the two disagree exactly where it matters: an entry whose widget
// is hidden -- media with nothing playing -- keeps its place in the list
// while occupying no width, and a capsule has to close over the widgets
// that are actually on the bar.
function pillNeighbour(step) {
  var host = slot.parent
  var kids = host ? host.children : null
  if (!kids) return null
  var at = -1
  for (var i = 0; i < kids.length; i++) { if (kids[i] === slot) { at = i; break } }
  if (at === -1) return null
  for (var j = at + step; j >= 0 && j < kids.length; j += step) {
    var other = kids[j]
    if (other && other.pillGroup !== undefined && other.visible && other.width > 0) return other
  }
  return null
}

function pillJoins(other) {
  return !!other && other.pillEnabled === true
    && slot.pillGroup !== "" && other.pillGroup === slot.pillGroup
}

readonly property bool pillFirst: !pillJoins(pillNeighbour(-1))
readonly property bool pillLast: !pillJoins(pillNeighbour(1))

// The far end of this slot's group. Bounded by the sibling count so a
// chain that somehow closes on itself cannot spin the binding.
readonly property var pillGroupEnd: {
  var last = slot
  var host = slot.parent
  var guard = host && host.children ? host.children.length : 0
  while (guard-- > 0) {
    var next = last.pillNeighbour(1)
    if (!last.pillJoins(next)) break
    last = next
  }
  return last
}

// How much of the slot the widget paints, along the bar axis. Most fill
// theirs, and those need no mask and get none of this.
// `pillMaskOwner` is the widget the cache was resolved against, so a slot
// that swaps widgets re-resolves without a second onActiveItemChanged
// handler -- upstream already owns that signal, and QML allows one.
property var pillMaskOwner: null
property var pillMaskItem: null
property real pillPaintStart: 0
property real pillPaintEnd: 0

function refreshPillPaint() {
  var extent = root.vertical ? slot.height : slot.width
  if (!slot.pillEnabled || !(extent > 0)) {
    slot.pillPaintStart = 0
    slot.pillPaintEnd = extent > 0 ? extent : 0
    return
  }
  if (slot.pillMaskOwner !== slot.activeItem) {
    slot.pillMaskOwner = slot.activeItem
    slot.pillMaskItem = root.maskedDescendant(slot.activeItem, 3)
  }
  var span = slot.pillMaskItem ? root.maskSpan(slot.pillMaskItem) : null
  slot.pillPaintStart = span ? span[0] : 0
  slot.pillPaintEnd = span ? span[1] : extent
}

onWidthChanged: refreshPillPaint()
onHeightChanged: refreshPillPaint()
onPillEnabledChanged: refreshPillPaint()
// A mask is a predicate with no change signal, so a reveal that slides in
// under one -- the tray drawer, over 600ms -- has to be watched instead.
// Only while the pointer is on the slot, plus a tail long enough for the
// animation to land after it leaves, and only for a widget that masks
// anything at all.
onHoveredChanged: pillSettle.restart()

Timer {
  id: pillSettle
  interval: 900
  repeat: false
}

Timer {
  running: slot.pillEnabled && slot.pillMaskItem !== null && (slot.hovered || pillSettle.running)
  interval: 32
  repeat: true
  onTriggered: slot.refreshPillPaint()
}

Rectangle {
  id: slotPill

  readonly property var groupEnd: slot.pillGroupEnd
  readonly property real crossInset: Style.space(2)
  readonly property real mainGap: Style.space(1)
  readonly property real spanEnd: {
    var last = groupEnd
    if (!last || last === slot) return slot.pillPaintEnd
    return (root.vertical ? last.y - slot.y : last.x - slot.x) + last.pillPaintEnd
  }
  readonly property real from: slot.pillPaintStart + mainGap
  readonly property real to: spanEnd - mainGap

  // A group's leading entry can be an empty slot -- neighbours are looked
  // up by what occupies width, so the first slot that does also reads as
  // the group's first, and both would paint the same capsule over each
  // other at double the alpha. A widget that hides itself takes its slot's
  // height down with its width and paints nothing either way; this says so
  // rather than leaning on it.
  visible: slot.pillEnabled && slot.pillFirst && slot.width > 0 && slot.height > 0 && to > from
  x: root.vertical ? crossInset : from
  y: root.vertical ? from : crossInset
  width: root.vertical ? Math.max(0, slot.width - crossInset * 2) : to - from
  height: root.vertical ? to - from : Math.max(0, slot.height - crossInset * 2)
  radius: Math.min(width, height) / 2
  color: root.pillFillFor(slot.pillGroup)
  border.width: 1
  border.color: root.pillBorderFor(slot.pillGroup)
  opacity: slot.dragSource ? 0.35 : 1.0

  // Both follow the theme, so both crossfade with it.
  Behavior on color {
    enabled: root.foregroundAnimationEnabled
    ColorAnimation { duration: 420; easing.type: Easing.InOutCubic }
  }

  Behavior on border.color {
    enabled: root.foregroundAnimationEnabled
    ColorAnimation { duration: 420; easing.type: Easing.InOutCubic }
  }
}

function cycleBackground() {
  // Pills keep the strip clear whatever the background says, so a cycle
  // would change nothing on screen. Leave pills instead: the bar lands on
  // the background the file already names.
  if (root.pills && root.shell && typeof root.shell.mutateShellConfig === "function") {
    root.shell.mutateShellConfig(function(config) {
      if (!Util.isPlainObject(config.bar)) config.bar = {}
      config.bar.pills = false
    })
    return
  }
  Util.execDetached("omarchy-bar background cycle")
}
